// Appends Nail Care ids 301-315 + Skin Care ids 316-350
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const ncT=`"Nail Care"`, ncTes=`"Cuidado de Uñas"`, ncPt=`"Nail Care"`, ncPtes=`"Cuidado de Uñas"`
const scT=`"Skin Care"`, scTes=`"Cuidado de la Piel"`, scPt=`"Skin Care"`, scPtes=`"Cuidado de la Piel"`

function fmt(q, t, tes, pt, ptes) {
  return `  { id: ${q.id}, topic: ${t}, topic_es: ${tes}, psi_topic: ${pt}, psi_topic_es: ${ptes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const NC = [
  { id: 301, question: "The nail technician's station should be organized to minimize cross-contamination risk by:", question_es: "La estación del técnico de uñas debe organizarse para minimizar el riesgo de contaminación cruzada:", options: ["Keeping a clear physical separation between the clean (disinfected implements, fresh products) and contaminated zones (used implements, discarded items) — used implements go immediately to the dirty container, single-use items discarded immediately after use, and new implements are only opened when needed", "Keeping all implements (used and clean) in the same container for efficiency — separation is not necessary during the service", "Placing all implements (including used ones) on the client-facing side of the table for easy client inspection", "Only separating implements at the end of the day — during service, implements can be freely mixed between clean and used zones"], options_es: ["Mantener una separación física clara entre las zonas limpia (implementos desinfectados, productos frescos) y contaminada (implementos usados, artículos desechados) — los implementos usados van inmediatamente al contenedor sucio, los artículos de uso único se desechan de inmediato después de su uso y los nuevos implementos solo se abren cuando son necesarios", "Mantener todos los implementos (usados y limpios) en el mismo contenedor para mayor eficiencia — la separación no es necesaria durante el servicio", "Colocar todos los implementos (incluidos los usados) en el lado del cliente de la mesa para una fácil inspección del cliente", "Solo separar los implementos al final del día — durante el servicio, los implementos se pueden mezclar libremente entre las zonas limpia y usada"], correct: 0, explanation: "The clean/contaminated zone separation is a fundamental infection control principle for nail stations. Once an implement contacts the client, it enters the contaminated zone. A clear workflow — clean implements in → contact client → immediately to contaminated container — prevents inadvertent reuse of contaminated items and protects subsequent clients from cross-contamination." },
  { id: 302, question: "When performing a manicure, if the client requests that the esthetician cut the cuticle very short, the esthetician should:", question_es: "Al realizar una manicura, si el cliente solicita que el esteticista corte la cutícula muy corta, el esteticista debe:", options: ["Explain that cutting living cuticle tissue (the actual seal at the nail fold) is not recommended — it removes the protective barrier that prevents infection, causes the cuticle to grow back thicker over time, and increases paronychia risk; offer to gently push back and trim only the dead skin (pterygium) instead", "Comply fully with the client's request — client preference always overrides professional recommendation", "Cut the cuticle as deeply as possible — short cuticles are always healthier than longer ones", "Refuse the service entirely — any client requesting cuticle cutting cannot receive manicure services"], options_es: ["Explicar que no se recomienda cortar el tejido de la cutícula vivo (el sello real en el pliegue ungueal) — elimina la barrera protectora que previene la infección, hace que la cutícula crezca más gruesa con el tiempo y aumenta el riesgo de paroniquia; ofrecer empujar suavemente hacia atrás y recortar solo la piel muerta (pterigión) en su lugar", "Cumplir completamente con la solicitud del cliente — la preferencia del cliente siempre anula la recomendación profesional", "Cortar la cutícula tan profundamente como posible — las cutículas cortas siempre son más saludables que las más largas", "Rechazar el servicio por completo — cualquier cliente que solicite cortar la cutícula no puede recibir servicios de manicura"], correct: 0, explanation: "Client education is a professional responsibility. Cutting living cuticle: (1) removes the waterproof seal at the nail fold junction, (2) introduces infection risk (paronychia), (3) stimulates the cuticle to grow back thicker and faster over time (trauma response). Offer the alternative: soften with cuticle remover, gently push back, trim only the non-living pterygium (dead skin on the nail plate). Educate while respecting client choice." },
  { id: 303, question: "A sanitation log for a nail station should record:", question_es: "Un registro de saneamiento para una estación de uñas debe registrar:", options: ["The date and time of disinfection procedures, the disinfectant product name and EPA registration number used, the implements that were disinfected, and the technician's name — this creates an audit trail demonstrating consistent protocol compliance", "Only client names and service types — sanitation activities do not require documentation at the nail station", "Only the brand of nail polish used for each client — product records are the primary documentation requirement", "Only incidents of sanitation failure — routine sanitation does not need to be documented"], options_es: ["La fecha y hora de los procedimientos de desinfección, el nombre del producto desinfectante y el número de registro de la EPA utilizado, los implementos que fueron desinfectados y el nombre del técnico — esto crea un rastro de auditoría que demuestra el cumplimiento consistente del protocolo", "Solo los nombres de los clientes y los tipos de servicio — las actividades de saneamiento no requieren documentación en la estación de uñas", "Solo la marca del esmalte de uñas utilizado para cada cliente — los registros de productos son el principal requisito de documentación", "Solo los incidentes de fallo de saneamiento — el saneamiento rutinario no necesita documentarse"], correct: 0, explanation: "Sanitation logs: (1) demonstrate compliance during TDLR inspections, (2) provide legal protection if a client claims they were infected at the establishment, (3) create accountability among staff, (4) identify patterns (e.g., a specific staff member skipping protocols). Required elements: date/time, product used (with EPA registration), implements treated, and the responsible technician's name." },
  { id: 304, question: "Which nail care step specifically addresses the removal of dead skin from the surface of the nail plate itself (not the cuticle surrounding the nail)?", question_es: "¿Cuál paso del cuidado de uñas aborda específicamente la eliminación de la piel muerta de la superficie de la placa ungueal misma (no la cutícula que rodea la uña)?", options: ["Applying cuticle remover to the nail plate — cuticle remover products contain keratin-dissolving alkaline chemicals (potassium hydroxide, sodium hydroxide) that dissolve the dead pterygium tissue that grows onto the nail plate surface from the proximal nail fold", "Applying nail dehydrator — dehydrators remove dead skin from the nail plate as their primary function", "Buffing with a 100-grit buffer — coarse buffing is specifically designed for dead skin removal", "Soaking in acetone — acetone dissolves dead skin from the nail plate surface in all cases"], options_es: ["Aplicar removedor de cutícula en la placa ungueal — los productos removedores de cutícula contienen químicos alcalinos que disuelven la queratina (hidróxido de potasio, hidróxido de sodio) que disuelven el tejido de pterigión muerto que crece sobre la superficie de la placa ungueal desde el pliegue ungueal proximal", "Aplicar deshidratador de uñas — los deshidratadores eliminan la piel muerta de la placa ungueal como su función principal", "Pulir con un buffer de 100 granos — el pulido grueso está específicamente diseñado para la eliminación de piel muerta", "Remojar en acetona — la acetona disuelve la piel muerta de la superficie de la placa ungueal en todos los casos"], correct: 0, explanation: "Cuticle remover (chemical cuticle softener) contains mild alkali (potassium hydroxide or sodium hydroxide) that dissolves the bonds in dead keratin. When applied to the nail plate surface, it dissolves the pterygium — the dead, translucent skin that migrates from the proximal nail fold onto the nail plate. After application and brief wait, the softened dead skin is pushed back with a pusher and trimmed/wiped away." },
  { id: 305, question: "The maximum safe temperature for a paraffin wax treatment for the hands is approximately:", question_es: "La temperatura máxima segura para un tratamiento de cera de parafina para las manos es aproximadamente:", options: ["125°F (52°C) — professional paraffin units heat wax to approximately 125°F, which is warm enough to be therapeutic but cool enough to avoid burns on intact, normally-sensitive skin; always test the temperature before the client's first dip", "200°F (93°C) — high temperatures are needed for the wax to penetrate the skin", "70°F (21°C) — paraffin should be at room temperature to prevent any burn risk", "250°F (121°C) — this is the minimum temperature at which paraffin provides therapeutic benefit"], options_es: ["125°F (52°C) — las unidades de parafina profesionales calientan la cera a aproximadamente 125°F, lo que es suficientemente cálido para ser terapéutico pero suficientemente fresco para evitar quemaduras en piel intacta y normalmente sensible; siempre pruebe la temperatura antes del primer baño del cliente", "200°F (93°C) — se necesitan temperaturas altas para que la cera penetre la piel", "70°F (21°C) — la parafina debe estar a temperatura ambiente para prevenir cualquier riesgo de quemadura", "250°F (121°C) — esta es la temperatura mínima a la que la parafina proporciona beneficio terapéutico"], correct: 0, explanation: "Professional paraffin units maintain wax at approximately 125–130°F (52–54°C). This range is: hot enough to be therapeutic (thermotherapy, improved circulation, skin softening), but cool enough to avoid burns on normal-sensation skin. Always test: dip your own wrist first, or have the client test a small area before full immersion. Lower temperature for heat-sensitive clients (diabetics with neuropathy)." },
  { id: 306, question: "Nail care clients should be advised to wear gloves during household cleaning because:", question_es: "Los clientes de cuidado de uñas deben ser aconsejados a usar guantes durante la limpieza del hogar porque:", options: ["Household cleaning products (bleach, ammonia, detergents) are highly alkaline and dissolve nail plate keratin, dry the cuticle, and rapidly remove nail polish — gloves protect both the nail enhancement or polish and the natural nail plate from chemical exposure and excessive water contact", "Gloves are only needed for industrial cleaning — household products are too mild to affect nails", "Wearing gloves prevents the nail from growing, slowing the need for manicure services", "Gloves during cleaning are only advisable for clients with enhancement products — natural nail clients do not need glove protection"], options_es: ["Los productos de limpieza del hogar (lejía, amoníaco, detergentes) son altamente alcalinos y disuelven la queratina de la placa ungueal, resecan la cutícula y eliminan rápidamente el esmalte de uñas — los guantes protegen tanto la mejora de uñas o el esmalte como la placa ungueal natural de la exposición química y el contacto excesivo con agua", "Los guantes solo se necesitan para la limpieza industrial — los productos del hogar son demasiado suaves para afectar las uñas", "Usar guantes durante la limpieza evita que la uña crezca, ralentizando la necesidad de servicios de manicura", "Los guantes durante la limpieza solo son recomendables para clientes con productos de mejoras — los clientes con uñas naturales no necesitan protección de guantes"], correct: 0, explanation: "Household cleaning is one of the most damaging activities for nail enhancements and nail health: (1) alkaline cleaners (bleach, ammonia, dish detergent) dry out and weaken nail keratin, (2) prolonged water exposure cycles hydrate/dehydrate nails causing stress, (3) cleaning chemicals rapidly soften and lift nail polish. Rubber gloves (cotton-lined for comfort) are the most effective protection for maintaining manicure longevity." },
  { id: 307, question: "An esthetics client who is taking blood thinners (anticoagulants) for a medical condition should be advised regarding nail services that:", question_es: "Un cliente de estética que está tomando anticoagulantes (medicamentos para diluir la sangre) por una condición médica debe ser asesorado con respecto a los servicios de uñas que:", options: ["Extra care must be taken to avoid any skin cuts or nicks during the service — patients on anticoagulants bleed more profusely from even minor cuts and may have difficulty stopping bleeding; inform the client and use extra gentle technique, particularly during cuticle care", "Blood thinners have no effect on nail services — proceed exactly as with any other client", "Clients on blood thinners must provide a physician's note clearing them for any nail service", "Clients on blood thinners cannot receive manicure services at all — any minor cut could be fatal"], options_es: ["Se debe tener un cuidado especial para evitar cualquier corte en la piel durante el servicio — los pacientes con anticoagulantes sangran más profusamente incluso de cortes menores y pueden tener dificultad para detener el sangrado; informe al cliente y use una técnica extra suave, particularmente durante el cuidado de la cutícula", "Los anticoagulantes no tienen ningún efecto en los servicios de uñas — proceda exactamente como con cualquier otro cliente", "Los clientes con anticoagulantes deben proporcionar una nota del médico autorizándolos para cualquier servicio de uñas", "Los clientes con anticoagulantes no pueden recibir servicios de manicura en absoluto — cualquier corte menor podría ser fatal"], correct: 0, explanation: "Anticoagulants (warfarin, apixaban, rivaroxaban, clopidogrel, aspirin) impair blood clotting. Minor cuts during cuticle care that would normally stop bleeding in 1–2 minutes may bleed significantly longer. Modification: extra gentle cuticle care, use cuticle remover chemistry rather than nippers where possible, inform the client before service, and be prepared with styptic and pressure if a nick occurs. Nail services are not contraindicated — just require extra care." },
  { id: 308, question: "In the context of nail care services, what does 'nail plate thinning' caused by over-buffing mean clinically?", question_es: "En el contexto de los servicios de cuidado de uñas, ¿qué significa clínicamente el 'adelgazamiento de la placa ungueal' causado por el limado excesivo?", options: ["Physical removal of nail plate keratin layers through abrasion — the nail plate has a finite thickness and repeated buffing removes surface layers until the plate becomes thin, flexible, and sensitive (pain from gentle pressure, heat sensitivity, and increased breakage risk)", "Nail buffing causes the nail plate to produce new keratin faster to compensate — thinning is actually beneficial to nail health", "Over-buffing only affects the shine of the nail — it has no effect on actual nail plate thickness or health", "Nail plate thinning from buffing only affects artificial nail products — natural nail plates cannot be thinned by buffing"], options_es: ["Eliminación física de las capas de queratina de la placa ungueal por abrasión — la placa ungueal tiene un grosor finito y el limado repetido elimina las capas superficiales hasta que la placa se vuelve delgada, flexible y sensible (dolor por presión suave, sensibilidad al calor y mayor riesgo de rotura)", "El limado de uñas hace que la placa ungueal produzca nueva queratina más rápido para compensar — el adelgazamiento es en realidad beneficioso para la salud de las uñas", "El limado excesivo solo afecta el brillo de la uña — no tiene ningún efecto en el grosor o la salud real de la placa ungueal", "El adelgazamiento de la placa ungueal por limado solo afecta los productos de uñas artificiales — las placas ungueales naturales no pueden adelgazarse por el limado"], correct: 0, explanation: "The nail plate is approximately 0.5–0.75mm thick. Buffing removes surface layers each time. Thinned nails: (1) appear whitish/translucent, (2) are flexible and easily bent, (3) are painful under light pressure, (4) are sensitive to temperature, (5) break easily. This damage is permanent until new nail grows out from the matrix. Prevention: limit buffing to monthly or less, use fine-grit buffers, gentle pressure only." },
  { id: 309, question: "A nail service client with Raynaud's phenomenon (episodes of finger blood vessel spasm causing white/blue/red color changes in cold) should:", question_es: "Un cliente de servicio de uñas con fenómeno de Raynaud (episodios de espasmo de los vasos sanguíneos de los dedos que causa cambios de color blanco/azul/rojo en el frío) debe:", options: ["Be kept warm during the service — avoid cold water soaks and cold implements (warm the water and tools to comfortable temperature); cold triggers are the most common cause of Raynaud's episodes, and a cold manicure environment can induce an episode", "Avoid all nail services — Raynaud's is an absolute contraindication for manicure", "Use extra-cold water for the soaking bowl — Raynaud's clients benefit from cold exposure therapy during nail services", "Receive aggressive hand massage to improve blood flow — vigorous massage always benefits Raynaud's clients"], options_es: ["Mantener al cliente caliente durante el servicio — evitar los baños de agua fría y los implementos fríos (calentar el agua y las herramientas a una temperatura cómoda); los desencadenantes de frío son la causa más común de los episodios de Raynaud, y un ambiente de manicura frío puede inducir un episodio", "Evitar todos los servicios de uñas — el Raynaud es una contraindicación absoluta para la manicura", "Usar agua extra fría para el tazón de remojo — los clientes con Raynaud se benefician de la terapia de exposición al frío durante los servicios de uñas", "Recibir un masaje de manos agresivo para mejorar el flujo sanguíneo — el masaje vigoroso siempre beneficia a los clientes con Raynaud"], correct: 0, explanation: "Raynaud's phenomenon causes episodic vasospasm triggered primarily by cold exposure. During nail services: use warm (not cold) soaking water, warm implements before use, keep the service room at a comfortable temperature, and avoid cold air from AC directed at the client's hands. Services are not contraindicated — gentle technique, warmth, and calm client positioning help prevent episodes." },
  { id: 310, question: "The reason nail files and buffers cannot be disinfected and must be single-use per client is:", question_es: "La razón por la que las limas y buffers de uñas no pueden desinfectarse y deben ser de uso único por cliente es:", options: ["Their abrasive surface is porous — the abrasive material contains microscopic spaces where nail debris, skin cells, and microorganisms become trapped beyond the reach of surface disinfectants; immersion in disinfectant cannot reach organisms embedded within the porous abrasive matrix", "They are too expensive to purchase new for each client — cost is the primary reason for single-use classification", "Files and buffers can actually be autoclaved — the single-use classification is a marketing strategy by manufacturers", "Only files used on infected nails must be discarded — files used on healthy nails can be cleaned and reused"], options_es: ["Su superficie abrasiva es porosa — el material abrasivo contiene espacios microscópicos donde los residuos de uñas, las células de la piel y los microorganismos quedan atrapados más allá del alcance de los desinfectantes de superficie; la inmersión en desinfectante no puede llegar a los organismos incrustados dentro de la matriz abrasiva porosa", "Son demasiado caras para comprar nuevas para cada cliente — el costo es la razón principal para la clasificación de uso único", "Las limas y los buffers se pueden esterilizar en autoclave — la clasificación de uso único es una estrategia de marketing de los fabricantes", "Solo las limas usadas en uñas infectadas deben desecharse — las limas usadas en uñas sanas se pueden limpiar y reutilizar"], correct: 0, explanation: "Nail files and buffers contain abrasive particles (sandpaper-like structure) with a porous structure that traps nail dust, skin cells, and microorganisms. Disinfectants work by surface contact — they cannot penetrate the porous matrix to reach embedded organisms. Autoclaving (heat) would destroy the abrasive substrate. This is why all porous nail implements (files, buffers, orangewood sticks) are single-use classified." },
  { id: 311, question: "Nail rebalancing (a fill or maintenance service) for acrylic nail enhancements is performed to:", question_es: "El rebalanceo de uñas (un relleno o servicio de mantenimiento) para las mejoras de uñas acrílicas se realiza para:", options: ["Maintain the structural integrity and appearance of the enhancement as the natural nail grows — approximately every 2–3 weeks the new growth creates a gap at the cuticle area, the enhancement thins at the stress point, and the surface shows lifting; filling addresses all of these to extend enhancement life", "Remove the old enhancement entirely and replace with a completely new set every visit", "Apply a fresh coat of polish over the existing enhancement without addressing structural issues", "Deepen the natural nail's color before reapplying the enhancement product"], options_es: ["Mantener la integridad estructural y la apariencia de la mejora a medida que la uña natural crece — aproximadamente cada 2–3 semanas el nuevo crecimiento crea un espacio en el área de la cutícula, la mejora se adelgaza en el punto de estrés y la superficie muestra levantamiento; el relleno aborda todos estos problemas para extender la vida de la mejora", "Eliminar la mejora antigua por completo y reemplazarla con un nuevo juego completo en cada visita", "Aplicar una capa fresca de esmalte sobre la mejora existente sin abordar los problemas estructurales", "Profundizar el color de la uña natural antes de volver a aplicar el producto de mejora"], correct: 0, explanation: "Enhancement fills/rebalances (typically every 2–3 weeks): (1) address new growth (fill the gap at the cuticle), (2) rebalance the structure (the apex shifts as the nail grows — add product to reposition it over the stress area), (3) smooth and reshape the surface, (4) address any lifting areas (remove lifted product to prevent moisture/bacteria trapped beneath). Full removal and replacement is only needed every 3–4 months or when significant damage occurs." },
  { id: 312, question: "When a nail enhancement (acrylic or gel) develops lifting from the natural nail plate, the esthetician should:", question_es: "Cuando una mejora de uñas (acrílico o gel) desarrolla levantamiento de la placa ungueal natural, el esteticista debe:", options: ["Remove the lifted portion before it fully separates — leaving lifted enhancement creates a pocket that traps moisture and bacteria, potentially leading to a green nail (Pseudomonas) or fungal infection; the area must be properly resealed or the enhancement rebalanced", "Apply more acrylic or gel over the lifted area to re-adhere it — pressing it down and covering is the correct repair technique", "Apply super glue under the lifted edge to re-bond the enhancement — this provides an immediate and permanent fix", "Leave the lifting to resolve on its own — lifting always self-corrects if left alone"], options_es: ["Eliminar la porción levantada antes de que se separe completamente — dejar la mejora levantada crea un bolsillo que atrapa humedad y bacterias, potencialmente conduciendo a una uña verde (Pseudomonas) o infección fúngica; el área debe sellarse adecuadamente o la mejora debe rebalancearse", "Aplicar más acrílico o gel sobre el área levantada para readherirla — presionarla hacia abajo y cubrirla es la técnica de reparación correcta", "Aplicar superpegamento bajo el borde levantado para volver a unir la mejora — esto proporciona una solución inmediata y permanente", "Dejar que el levantamiento se resuelva por sí solo — el levantamiento siempre se autocorrige si se deja solo"], correct: 0, explanation: "Lifting creates a pocket between the natural nail and the enhancement that is: warm, moist, and dark — ideal for bacterial (Pseudomonas) and fungal growth. Immediate action: remove the lifted portion, clean the exposed nail plate, and reseal the area. Applying product over a lifted area seals in potential pathogens and moisture — this is a serious infection risk. The green nail from Pseudomonas is the most common complication of unaddressed lifting." },
  { id: 313, question: "A professional nail brush (clean-up brush) containing acetone or nail cleanser is used during gel or acrylic nail services to:", question_es: "Un pincel de uñas profesional (pincel de limpieza) que contiene acetona o limpiador de uñas se usa durante los servicios de gel o uñas acrílicas para:", options: ["Remove excess product from the surrounding skin and cuticle area before curing (gel) or setting (acrylic) — this prevents product from bonding to the skin at the nail fold, which would cause lifting and client discomfort when the bonded skin is flexed", "Apply the acrylic or gel product to the nail — it serves as the primary application tool", "Remove polish from the nail plate before beginning the enhancement application", "Apply cuticle oil after the enhancement is complete to add shine"], options_es: ["Eliminar el exceso de producto de la piel circundante y el área de la cutícula antes del curado (gel) o el fraguado (acrílico) — esto evita que el producto se adhiera a la piel en el pliegue ungueal, lo que causaría levantamiento y molestias al cliente cuando la piel unida se flexiona", "Aplicar el producto de acrílico o gel en la uña — sirve como la herramienta principal de aplicación", "Eliminar el esmalte de la placa ungueal antes de comenzar la aplicación de mejoras", "Aplicar aceite de cutícula después de que la mejora esté completa para añadir brillo"], correct: 0, explanation: "Clean-up brush technique is critical for professional enhancement results. Before curing gel or before acrylic sets: use a brush dampened with cleanser (IPA or acetone, depending on product) to carefully remove any product that has flowed onto the proximal nail fold or lateral nail folds. Product bonded to the skin: (1) causes lifting as the skin naturally flexes, (2) can cause allergic sensitization, (3) creates an aesthetically unappealing finished result." },
  { id: 314, question: "A client who is allergic to cyanoacrylate (nail glue) used for tip application needs:", question_es: "Un cliente que es alérgico al cianoacrilato (pegamento de uñas) usado para la aplicación de puntas necesita:", options: ["An alternative nail extension method that does not use cyanoacrylate adhesive — options include forms with acrylic or gel overlay (no adhesive required), or the esthetician should consult with the client's allergist about safe alternatives", "To avoid all nail services entirely — cyanoacrylate allergy permanently disqualifies all nail services", "A higher-quality cyanoacrylate brand — premium glues do not cause allergic reactions", "To wear hypoallergenic gloves during the service — this prevents the adhesive from contacting the skin that causes the allergy"], options_es: ["Un método alternativo de extensión de uñas que no use adhesivo de cianoacrilato — las opciones incluyen formas con superposición de acrílico o gel (no se requiere adhesivo), o el esteticista debe consultar con el alergólogo del cliente sobre alternativas seguras", "Evitar todos los servicios de uñas por completo — la alergia al cianoacrilato descalifica permanentemente todos los servicios de uñas", "Una marca de cianoacrilato de mayor calidad — los pegamentos premium no causan reacciones alérgicas", "Usar guantes hipoalergénicos durante el servicio — esto evita que el adhesivo entre en contacto con la piel que causa la alergia"], correct: 0, explanation: "Cyanoacrylate (nail tip glue, nail wrap resin) allergy is a contact sensitization. It causes allergic contact dermatitis at the nail fold and surrounding skin. Alternative approaches: (1) nail forms (no adhesive needed — acrylic or gel is built directly on the form under the free edge), (2) sculpted gel extensions on forms. The allergy does not preclude all nail services — only those using cyanoacrylate adhesive specifically." },
  { id: 315, question: "The appropriate response when a client's natural nail breaks during a manicure service (a stress fracture in the nail plate) is:", question_es: "La respuesta apropiada cuando la uña natural de un cliente se rompe durante un servicio de manicura (una fractura de estrés en la placa ungueal) es:", options: ["Repair the break using a nail wrap technique (silk or fiberglass patch + resin) or a nail repair product, file smooth, and continue the manicure — a small repair provides structural reinforcement while the nail grows out", "Immediately terminate the manicure service — broken nails cannot receive any further services", "Cut all other nails to match the length of the broken nail — length consistency is the only appropriate response", "Apply super glue to the break and leave it without finishing — super glue alone is a complete nail repair"], options_es: ["Reparar la rotura usando una técnica de envoltura de uñas (parche de seda o fibra de vidrio + resina) o un producto de reparación de uñas, limar suavemente y continuar la manicura — una pequeña reparación proporciona refuerzo estructural mientras la uña crece", "Terminar inmediatamente el servicio de manicura — las uñas rotas no pueden recibir ningún servicio adicional", "Cortar todas las demás uñas para igualar la longitud de la uña rota — la consistencia de longitud es la única respuesta apropiada", "Aplicar superpegamento en la rotura y dejarla sin terminar — el superpegamento solo es una reparación de uña completa"], correct: 0, explanation: "A stress fracture or break during service can be repaired with a nail wrap patch: (1) clean the break, (2) cut a small piece of silk or fiberglass mesh slightly larger than the break, (3) apply with resin (cyanoacrylate), (4) activate with activator spray, (5) buff smooth, (6) continue manicure. The patch reinforces the break site while new nail grows out. This is a standard nail repair service, not an indication to end the service." },
]

const SC = [
  { id: 316, question: "The epidermis, the outermost layer of skin, consists of how many layers?", question_es: "La epidermis, la capa más externa de la piel, consta de cuántas capas?", options: ["Five layers in thick skin (palms, soles): stratum basale, stratum spinosum, stratum granulosum, stratum lucidum, and stratum corneum — on most body skin, the stratum lucidum is absent, leaving four functional layers", "Two layers — the epidermis is a simple two-layer structure", "Seven layers — the epidermis has seven distinct zones that require separate treatment", "Only one layer — the epidermis is a single sheet of cells covering the dermis"], options_es: ["Cinco capas en piel gruesa (palmas, plantas): estrato basal, estrato espinoso, estrato granuloso, estrato lúcido y estrato córneo — en la mayoría de la piel del cuerpo, el estrato lúcido está ausente, dejando cuatro capas funcionales", "Dos capas — la epidermis es una estructura simple de dos capas", "Siete capas — la epidermis tiene siete zonas distintas que requieren tratamiento separado", "Solo una capa — la epidermis es una sola hoja de células que cubre la dermis"], correct: 0, explanation: "The epidermis has 5 layers (in thick skin) from deep to superficial: (1) Stratum basale (germinativum) — deepest, contains stem cells that produce all other epidermal cells; (2) Stratum spinosum — several layers of keratinocytes connected by desmosomes; (3) Stratum granulosum — cells produce lamellar granules releasing lipids that waterproof the skin; (4) Stratum lucidum — only in thick skin (palms, soles); (5) Stratum corneum — outermost, cornified dead cells." },
  { id: 317, question: "The stratum basale (basal layer) of the epidermis is important for esthetics because:", question_es: "El estrato basal (capa basal) de la epidermis es importante para la estética porque:", options: ["It contains the stem cells (basal keratinocytes) that produce all other epidermal cells — new skin cells are born here and migrate upward through the layers over approximately 28–30 days until they reach the stratum corneum and are shed; it also contains melanocytes that produce skin-color pigment", "It is the layer where collagen and elastin are produced — the structural proteins of the skin", "It is the outermost layer of skin that estheticians treat directly in all skin care services", "It contains only dead cells — it is the layer that forms the skin's primary barrier to chemical penetration"], options_es: ["Contiene las células madre (queratinocitos basales) que producen todas las demás células epidérmicas — las nuevas células de la piel nacen aquí y migran hacia arriba a través de las capas durante aproximadamente 28–30 días hasta que llegan al estrato córneo y se descaman; también contiene melanocitos que producen el pigmento del color de la piel", "Es la capa donde se producen el colágeno y la elastina — las proteínas estructurales de la piel", "Es la capa más externa de la piel que los esteticistas tratan directamente en todos los servicios de cuidado de la piel", "Contiene solo células muertas — es la capa que forma la barrera primaria de la piel a la penetración química"], correct: 0, explanation: "The stratum basale: (1) contains keratinocyte stem cells that undergo mitosis to generate all epidermal cells — these divide and push older cells upward in the keratinization process; (2) contains melanocytes (produce melanin pigment — ~1 per 10 keratinocytes); (3) anchors the epidermis to the dermis via the basement membrane. Skin cell turnover (basale to corneum) takes ~28 days in young adults, slower with age." },
  { id: 318, question: "The stratum corneum is significant in esthetics because:", question_es: "El estrato córneo es significativo en la estética porque:", options: ["It is the outermost layer of skin — the primary barrier function, the target of many esthetics treatments (exfoliation, hydration, moisturization), and its condition directly determines the skin's appearance (smooth, rough, dull, bright)", "It is the deepest layer of the epidermis where new cells are produced", "It contains living cells that actively produce collagen in response to esthetics treatments", "It is found only in very thick skin areas (palms and soles) and is irrelevant to facial esthetics"], options_es: ["Es la capa más externa de la piel — la función de barrera primaria, el objetivo de muchos tratamientos de estética (exfoliación, hidratación, humectación) y su condición determina directamente la apariencia de la piel (suave, áspera, opaca, brillante)", "Es la capa más profunda de la epidermis donde se producen nuevas células", "Contiene células vivas que producen activamente colágeno en respuesta a los tratamientos de estética", "Se encuentra solo en áreas de piel muy gruesa (palmas y plantas) y es irrelevante para la estética facial"], correct: 0, explanation: "The stratum corneum (SC) is a stack of dead, flat, cornified keratinocytes (corneocytes) embedded in a lipid matrix — the 'brick and mortar' structure. It provides: (1) water barrier (prevents TEWL), (2) protection from UV, chemicals, microorganisms, (3) mechanical protection. Most topical products work at the SC level. Exfoliation removes corneocytes to improve texture, brightness, and product penetration to lower SC layers." },
  { id: 319, question: "Melanocytes in the basal layer of the epidermis produce melanin pigment that:", question_es: "Los melanocitos en la capa basal de la epidermis producen pigmento de melanina que:", options: ["Protects the skin and underlying tissues from UV radiation by absorbing UV light and distributing it harmlessly as heat — melanin is the skin's primary natural photoprotective mechanism, and its production is stimulated by UV exposure (tanning response)", "Causes skin aging — melanin accumulation causes all visible signs of aging", "Only provides skin color with no protective function — pigmentation is purely cosmetic", "Is produced only in dark-skinned individuals — lighter-skinned individuals have no melanocytes"], options_es: ["Protege la piel y los tejidos subyacentes de la radiación UV al absorber la luz UV y distribuirla inofensivamente como calor — la melanina es el mecanismo fotoprotector natural primario de la piel, y su producción es estimulada por la exposición UV (respuesta al bronceado)", "Causa el envejecimiento de la piel — la acumulación de melanina causa todos los signos visibles del envejecimiento", "Solo proporciona color de piel sin ninguna función protectora — la pigmentación es puramente cosmética", "Solo se produce en individuos de piel oscura — los individuos de piel más clara no tienen melanocitos"], correct: 0, explanation: "All humans have approximately the same number of melanocytes per unit area of skin — skin color differences arise from differences in melanin type (eumelanin = brown/black vs phaeomelanin = red/yellow), melanin amount, and melanin distribution. Melanin absorbs UV photons, converting the energy to heat — protecting DNA from UV damage. UV exposure triggers increased melanin production (tanning) as a protective response." },
  { id: 320, question: "Langerhans cells in the epidermis are relevant to esthetics because:", question_es: "Las células de Langerhans en la epidermis son relevantes para la estética porque:", options: ["They are the skin's primary immune sentinel cells — they capture antigens (including cosmetic ingredients that penetrate the skin) and initiate immune responses, including allergic contact sensitization reactions to skin care product ingredients", "They produce collagen and elastin in the epidermis for structural support", "They are the cells responsible for skin exfoliation — they detach from the skin surface as shed corneocytes", "They produce sebum for the skin's surface through sebaceous micro-glands embedded in the epidermis"], options_es: ["Son las células centinela inmunes primarias de la piel — capturan antígenos (incluidos los ingredientes cosméticos que penetran la piel) e inician respuestas inmunes, incluidas las reacciones de sensibilización de contacto alérgico a los ingredientes de los productos para el cuidado de la piel", "Producen colágeno y elastina en la epidermis para el soporte estructural", "Son las células responsables de la exfoliación de la piel — se desprenden de la superficie de la piel como corneocitos descamados", "Producen sebo para la superficie de la piel a través de micro-glándulas sebáceas incrustadas en la epidermis"], correct: 0, explanation: "Langerhans cells (LC) are dendritic immune cells in the epidermis (stratum spinosum). They are antigen-presenting cells — they sample the skin for foreign substances and activate T-lymphocytes, initiating immune responses. In esthetics: LCs are responsible for allergic contact sensitization to cosmetic ingredients (fragrances, preservatives, chemical UV filters). Repeated exposure to sensitizing ingredients first triggers LC-mediated sensitization, then subsequent exposures cause overt allergic reactions." },
  { id: 321, question: "The dermis, the layer beneath the epidermis, contains which structures relevant to esthetics?", question_es: "La dermis, la capa debajo de la epidermis, contiene cuáles estructuras relevantes para la estética?", options: ["Collagen fibers (provide skin tensile strength and firmness), elastin fibers (provide elasticity and recoil), fibroblasts (produce collagen/elastin/hyaluronic acid), blood vessels (supply nutrients), lymphatics, nerve endings, hair follicles, sebaceous glands, and sweat glands", "Only dead cells — the dermis contains no living structures", "Only blood vessels and nerves — the dermis has no structural proteins", "Only melanocytes — the dermis is where all skin pigmentation originates"], options_es: ["Fibras de colágeno (proporcionan resistencia y firmeza tensil a la piel), fibras de elastina (proporcionan elasticidad y recuperación), fibroblastos (producen colágeno/elastina/ácido hialurónico), vasos sanguíneos (suministran nutrientes), linfáticos, terminaciones nerviosas, folículos pilosos, glándulas sebáceas y glándulas sudoríparas", "Solo células muertas — la dermis no contiene estructuras vivas", "Solo vasos sanguíneos y nervios — la dermis no tiene proteínas estructurales", "Solo melanocitos — la dermis es donde se origina toda la pigmentación de la piel"], correct: 0, explanation: "The dermis is divided into: (1) Papillary dermis (superficial) — loose connective tissue with capillary loops that nourish the epidermis; (2) Reticular dermis (deep) — dense connective tissue with thick collagen and elastin bundles. Key structures: fibroblasts (main cell type — produce collagen, elastin, hyaluronic acid), blood vessels, lymphatics, sensory nerve endings, hair follicles with arrector pili muscles, sebaceous glands, eccrine and apocrine sweat glands." },
  { id: 322, question: "Collagen in the dermis is significant to esthetics because:", question_es: "El colágeno en la dermis es significativo para la estética porque:", options: ["Collagen provides the skin's structural support and firmness — it is the most abundant protein in the dermis; loss of collagen with aging, UV exposure, and inflammation leads to skin laxity, wrinkles, and reduced firmness that many esthetics treatments aim to address", "Collagen is only found in the epidermis — the dermis contains only elastin", "Collagen provides skin's elasticity and its ability to stretch and recoil — loss of collagen causes loss of elasticity", "Collagen in the skin is identical to dietary collagen and increases when clients consume collagen supplements"], options_es: ["El colágeno proporciona el soporte estructural y la firmeza de la piel — es la proteína más abundante en la dermis; la pérdida de colágeno con el envejecimiento, la exposición UV y la inflamación conduce a la laxitud cutánea, las arrugas y la firmeza reducida que muchos tratamientos de estética intentan abordar", "El colágeno solo se encuentra en la epidermis — la dermis contiene solo elastina", "El colágeno proporciona la elasticidad de la piel y su capacidad para estirarse y recuperarse — la pérdida de colágeno causa pérdida de elasticidad", "El colágeno en la piel es idéntico al colágeno dietético y aumenta cuando los clientes consumen suplementos de colágeno"], correct: 0, explanation: "Collagen (primarily Type I and III in skin) provides tensile strength and structural scaffolding. Fibroblasts synthesize it. Collagen production decreases ~1% per year after age 20, and UV radiation (photoaging) dramatically accelerates degradation through collagenase enzymes. The cosmetic consequence: skin laxity, deeper wrinkles, and loss of the 'bounce' of young skin. Retinoids, vitamin C, and growth factors stimulate fibroblast collagen synthesis." },
  { id: 323, question: "Transepidermal water loss (TEWL) is relevant to skin care because:", question_es: "La pérdida de agua transepidérmica (TEWL) es relevante para el cuidado de la piel porque:", options: ["TEWL is the passive evaporation of water from the skin through the epidermis — an intact skin barrier minimizes TEWL; damaged or disrupted barriers (from over-exfoliation, harsh cleansers, irritants) increase TEWL, leading to dehydration and the sensation of tight, dry, sensitive skin", "TEWL only occurs in oily skin types — dry skin has no transepidermal water loss", "TEWL is beneficial — high TEWL indicates healthy skin barrier function and effective toxin elimination", "TEWL is the amount of water the skin can absorb from topical products — products with high TEWL bring more water into the skin"], options_es: ["La TEWL es la evaporación pasiva de agua desde la piel a través de la epidermis — una barrera cutánea intacta minimiza la TEWL; las barreras dañadas o perturbadas (por la exfoliación excesiva, los limpiadores agresivos, los irritantes) aumentan la TEWL, lo que lleva a la deshidratación y la sensación de piel apretada, seca y sensible", "La TEWL solo ocurre en tipos de piel grasa — la piel seca no tiene pérdida de agua transepidérmica", "La TEWL es beneficiosa — una TEWL alta indica una función de barrera cutánea saludable y una eliminación efectiva de toxinas", "La TEWL es la cantidad de agua que la piel puede absorber de los productos tópicos — los productos con alta TEWL llevan más agua a la piel"], correct: 0, explanation: "TEWL is a measure of the skin's barrier integrity — specifically how much water passively diffuses out through the stratum corneum. Normal skin has low TEWL (intact lipid barrier). Compromised skin has high TEWL — the lipid matrix between corneocytes is disrupted, allowing water to escape more rapidly. Signs of high TEWL: tightness, flakiness, sensitivity, reactive skin. Treatment: restore the barrier with occlusives, ceramides, and lipid-replenishing products." },
  { id: 324, question: "The Fitzpatrick skin type scale classifies skin into six types primarily based on:", question_es: "La escala de tipo de piel de Fitzpatrick clasifica la piel en seis tipos principalmente basándose en:", options: ["Skin's response to UV exposure — Type I (always burns, never tans) through Type VI (never burns, deeply pigmented) — the scale helps estheticians assess sun damage risk, select appropriate exfoliation strength, and predict reactions to treatments like chemical peels and laser", "Age of the client — Types I through VI correspond to age decades (20s, 30s, 40s, etc.)", "The amount of natural melanin visible in the skin color only — not considering UV response", "The client's ancestry — Fitzpatrick types correspond to specific geographic regions of origin"], options_es: ["La respuesta de la piel a la exposición UV — Tipo I (siempre se quema, nunca se broncea) hasta el Tipo VI (nunca se quema, profundamente pigmentada) — la escala ayuda a los esteticistas a evaluar el riesgo de daño solar, seleccionar la intensidad de exfoliación apropiada y predecir las reacciones a tratamientos como los peels químicos y el láser", "La edad del cliente — los Tipos I al VI corresponden a décadas de edad (20, 30, 40, etc.)", "La cantidad de melanina natural visible en el color de la piel solo — sin considerar la respuesta UV", "La ascendencia del cliente — los tipos de Fitzpatrick corresponden a regiones geográficas específicas de origen"], correct: 0, explanation: "The Fitzpatrick Scale: Type I — very fair, always burns/never tans (highest skin cancer risk); Type II — fair, usually burns/rarely tans; Type III — medium, sometimes burns/gradually tans; Type IV — olive, rarely burns/tans easily; Type V — brown, very rarely burns/tans very easily; Type VI — dark brown/black, never burns/always deeply pigments. Crucial for esthetics: higher types (IV–VI) have greater post-inflammatory hyperpigmentation risk from aggressive treatments." },
  { id: 325, question: "The main functions of sebum (produced by the sebaceous glands) in skin physiology include:", question_es: "Las principales funciones del sebo (producido por las glándulas sebáceas) en la fisiología cutánea incluyen:", options: ["Skin surface lubrication, contribution to the acid mantle (lowering surface pH to inhibit pathogen growth), providing antibacterial and antifungal activity, and forming part of the skin's barrier layer that helps regulate moisture", "Sebum is entirely detrimental — it causes acne, enlarged pores, and skin aging with no beneficial functions", "Only UV protection — sebum acts as a natural sunscreen on the skin surface", "Only cooling the skin — sebum is the primary thermoregulatory secretion of the skin"], options_es: ["Lubricación de la superficie de la piel, contribución al manto ácido (bajando el pH de la superficie para inhibir el crecimiento de patógenos), proporcionando actividad antibacteriana y antifúngica y formando parte de la capa de barrera de la piel que ayuda a regular la humedad", "El sebo es completamente perjudicial — causa acné, poros agrandados y envejecimiento de la piel sin funciones beneficiosas", "Solo protección UV — el sebo actúa como protector solar natural en la superficie de la piel", "Solo enfriar la piel — el sebo es la secreción termorreguladora primaria de la piel"], correct: 0, explanation: "Sebum functions: (1) emollients/surface lubricant (keeps skin supple), (2) contributes to the acid mantle (pH 4.5–5.5) by mixing with sweat, (3) contains fatty acids with mild antibacterial/antifungal activity, (4) delivers antioxidants (vitamin E/squalene) to skin surface. Problems arise when sebum production is excessive (oily skin, acne) or deficient (dry, sensitive skin with compromised barrier)." },
  { id: 326, question: "In esthetics, 'dehydrated skin' differs from 'dry skin' because:", question_es: "En la estética, la 'piel deshidratada' difiere de la 'piel seca' porque:", options: ["Dry skin is a skin type (characterized by reduced sebum production — a structural/genetic condition), while dehydrated skin is a temporary condition of insufficient water content in the stratum corneum — dehydrated skin can occur in any skin type including oily skin", "Dry skin only occurs in cold weather while dehydrated skin is a permanent genetic skin type", "They are identical conditions that are simply described differently in different professional contexts", "Dehydrated skin has too much sebum while dry skin has too little — the lipid content is the differentiating factor"], options_es: ["La piel seca es un tipo de piel (caracterizada por la reducción de la producción de sebo — una condición estructural/genética), mientras que la piel deshidratada es una condición temporal de contenido de agua insuficiente en el estrato córneo — la piel deshidratada puede ocurrir en cualquier tipo de piel incluida la piel grasa", "La piel seca solo ocurre en el clima frío mientras que la piel deshidratada es un tipo de piel genético permanente", "Son condiciones idénticas que simplemente se describen de manera diferente en diferentes contextos profesionales", "La piel deshidratada tiene demasiado sebo mientras que la piel seca tiene muy poco — el contenido lipídico es el factor diferenciador"], correct: 0, explanation: "Critical esthetics distinction: Dry skin type = lack of sebum (lipid deficiency) — permanent/genetic, managed with emollient and occlusive products. Dehydrated skin = lack of water in the stratum corneum — temporary, can affect any skin type (even oily skin can be dehydrated). Dehydrated skin signs: tightness, fine lines visible when skin is pressed, shininess (in oily-dehydrated skin). Treatment: humectants (hyaluronic acid, glycerin) rather than oil-based products." },
  { id: 327, question: "Alpha hydroxy acids (AHAs) used in professional esthetics are primarily effective because:", question_es: "Los ácidos alfa hidróxidos (AHAs) usados en la estética profesional son principalmente efectivos porque:", options: ["They loosen the bonds between corneocytes in the stratum corneum — AHAs weaken the intercellular 'glue' (desmosomes) holding dead skin cells together, facilitating exfoliation; at higher concentrations they penetrate deeper for more significant resurfacing", "They kill bacteria in the skin — AHAs are primarily antimicrobial agents used to prevent breakouts", "They stimulate collagen production directly in the dermis by activating fibroblasts through the epidermis", "They physically scrub away dead skin cells through mechanical abrasion"], options_es: ["Aflojan los lazos entre los corneocitos en el estrato córneo — los AHAs debilitan el 'pegamento' intercelular (desmosomas) que mantiene unidas las células de la piel muerta, facilitando la exfoliación; a concentraciones más altas penetran más profundamente para una reaparición más significativa", "Matan las bacterias en la piel — los AHAs son principalmente agentes antimicrobianos usados para prevenir brotes", "Estimulan la producción de colágeno directamente en la dermis al activar los fibroblastos a través de la epidermis", "Limpian físicamente las células muertas de la piel a través de la abrasión mecánica"], correct: 0, explanation: "AHAs (glycolic acid from sugarcane, lactic acid from milk, mandelic acid from almonds, citric acid, malic acid, tartaric acid) work through chemical exfoliation: they reduce calcium ion concentration in the stratum corneum, weakening the ionic bonds between corneocytes (cohesins), causing the dead cells to slough off. Benefits: improved texture, brightness, reduced hyperpigmentation, stimulation of epidermal renewal and collagen synthesis." },
  { id: 328, question: "Beta hydroxy acid (BHA), specifically salicylic acid, is particularly beneficial for acne-prone skin because:", question_es: "El ácido beta hidróxi (BHA), específicamente el ácido salicílico, es particularmente beneficioso para la piel propensa al acné porque:", options: ["Salicylic acid is oil-soluble (lipophilic) — unlike AHAs (water-soluble), BHA can penetrate into the sebum-filled follicle to exfoliate the pore lining and dissolve comedone material; it also has anti-inflammatory properties", "Salicylic acid is an antibiotic that kills all acne-causing bacteria on contact", "BHA works by increasing sebum production to flush out clogged pores naturally", "BHA provides only surface exfoliation identical to AHAs — the follicle-penetrating advantage of BHA is a marketing myth"], options_es: ["El ácido salicílico es liposoluble (lipofílico) — a diferencia de los AHAs (hidrosolubles), el BHA puede penetrar en el folículo lleno de sebo para exfoliar el revestimiento del poro y disolver el material del comedón; también tiene propiedades antiinflamatorias", "El ácido salicílico es un antibiótico que mata todas las bacterias causantes del acné al contacto", "El BHA funciona aumentando la producción de sebo para eliminar naturalmente los poros obstruidos", "El BHA proporciona solo exfoliación superficial idéntica a los AHAs — la ventaja de penetración del folículo del BHA es un mito de marketing"], correct: 0, explanation: "Salicylic acid (BHA) key properties: (1) lipophilic — dissolves in sebum, allowing follicular penetration; (2) keratolytic — breaks down keratin bonds, exfoliating inside the follicle; (3) comedolytic — dissolves the keratin plug in comedones; (4) anti-inflammatory — reduces redness and inflammation of acne lesions; (5) mild antimicrobial. These properties make it uniquely effective for oily, acne-prone skin compared to water-soluble AHAs." },
  { id: 329, question: "In skin care, humectants differ from emollients in that:", question_es: "En el cuidado de la piel, los humectantes difieren de los emolientes en que:", options: ["Humectants (hyaluronic acid, glycerin, urea, honey) attract and bind water from the environment or deeper skin layers to the stratum corneum — they hydrate; emollients (shea butter, plant oils, fatty acids) fill in gaps between corneocytes and soften the skin's surface texture — they condition", "Humectants seal the skin's surface to prevent water loss while emollients attract water from the environment", "Humectants are synthetic ingredients; emollients are always natural, plant-derived ingredients", "They are identical in function — humectant and emollient are interchangeable terms used by different manufacturers"], options_es: ["Los humectantes (ácido hialurónico, glicerina, urea, miel) atraen y unen agua del ambiente o de las capas más profundas de la piel al estrato córneo — hidratan; los emolientes (manteca de karité, aceites vegetales, ácidos grasos) rellenan los espacios entre los corneocitos y suavizan la textura superficial de la piel — la acondicionan", "Los humectantes sellan la superficie de la piel para prevenir la pérdida de agua mientras que los emolientes atraen agua del ambiente", "Los humectantes son ingredientes sintéticos; los emolientes siempre son ingredientes naturales de origen vegetal", "Son idénticos en función — humectante y emoliente son términos intercambiables usados por diferentes fabricantes"], correct: 0, explanation: "Skin care ingredient functions: Humectants = attract/bind water (hygroscopic). Key humectants: hyaluronic acid (holds 1000× its weight in water), glycerin, urea, sodium PCA, honey. Emollients = fill intercellular spaces, soften skin surface, smooth texture. Key emollients: plant oils, shea butter, fatty acids (palmitic, stearic, oleic), ceramides. Occlusives (petrolatum, mineral oil, beeswax) = seal the surface to prevent TEWL. A complete moisturizer uses all three." },
  { id: 330, question: "UVA and UVB radiation differ in their effects on the skin in that:", question_es: "La radiación UVA y UVB difiere en sus efectos en la piel en que:", options: ["UVA (320–400nm) penetrates more deeply to the dermis, is responsible for photoaging (wrinkles, loss of elasticity, hyperpigmentation), and is present throughout daylight hours year-round — even through glass; UVB (280–320nm) primarily affects the epidermis, causes sunburn, and is the primary driver of skin cancer", "UVA only occurs outdoors in summer while UVB penetrates glass and occurs year-round", "UVA causes sunburn while UVB causes tanning — their skin effects are opposite to what is commonly taught", "UVA and UVB have identical effects on skin — the only difference is their wavelength designation"], options_es: ["La UVA (320–400nm) penetra más profundamente en la dermis, es responsable del fotoenvejecimiento (arrugas, pérdida de elasticidad, hiperpigmentación) y está presente durante todo el día durante todo el año — incluso a través del vidrio; la UVB (280–320nm) afecta principalmente a la epidermis, causa quemaduras solares y es el principal impulsor del cáncer de piel", "La UVA solo ocurre al aire libre en verano mientras que la UVB penetra el vidrio y ocurre durante todo el año", "La UVA causa quemaduras solares mientras que la UVB causa bronceado — sus efectos en la piel son opuestos a lo que comúnmente se enseña", "La UVA y la UVB tienen efectos idénticos en la piel — la única diferencia es su designación de longitud de onda"], correct: 0, explanation: "UVA ('Aging'): 95% of UV reaching Earth's surface; penetrates to dermis; causes photo-oxidative damage (free radicals), collagen/elastin degradation, hyperpigmentation, melanoma; constant year-round, penetrates clouds and glass. UVB ('Burning'): 5% of UV; primarily affects epidermis; causes direct DNA damage (thymine dimers), sunburn, basal/squamous cell carcinoma, some melanoma; strongest midday, summer, lower latitudes, blocked by glass. Broad-spectrum SPF protects against both." },
  { id: 331, question: "SPF (Sun Protection Factor) in sunscreen products specifically measures:", question_es: "El SPF (Factor de Protección Solar) en los productos de protector solar mide específicamente:", options: ["The degree of protection against UVB radiation — SPF 30 means it takes 30 times longer for UVB to cause a minimal erythema dose (slight reddening) compared to unprotected skin; SPF does not directly measure UVA protection", "The total protection against all UV radiation including UVA and UVB equally", "The number of hours a single sunscreen application remains effective regardless of conditions", "The concentration of active UV-blocking ingredients in the product"], options_es: ["El grado de protección contra la radiación UVB — SPF 30 significa que toma 30 veces más tiempo para que la UVB cause una dosis mínima de eritema (enrojecimiento ligero) en comparación con la piel sin protección; el SPF no mide directamente la protección UVA", "La protección total contra toda la radiación UV incluida UVA y UVB igualmente", "El número de horas que una sola aplicación de protector solar permanece efectiva independientemente de las condiciones", "La concentración de ingredientes activos bloqueadores de UV en el producto"], correct: 0, explanation: "SPF measures UVB protection specifically. SPF 15 = blocks ~93% UVB; SPF 30 = ~97%; SPF 50 = ~98%. No sunscreen blocks 100% of UVB. For UVA protection, look for 'broad spectrum' designation (required by FDA for products claiming broad-spectrum protection). SPF does not mean hours of protection — duration depends on activity (sweating, swimming), application amount, and skin. Reapplication every 2 hours is standard guidance." },
  { id: 332, question: "Physical (mineral) sunscreens containing zinc oxide and/or titanium dioxide differ from chemical sunscreens in that:", question_es: "Los protectores solares físicos (minerales) que contienen óxido de zinc y/o dióxido de titanio difieren de los protectores solares químicos en que:", options: ["Physical sunscreens reflect and scatter UV radiation at the skin's surface — they work immediately upon application, are less likely to cause irritation (good for sensitive skin), are generally photostable, and provide broad-spectrum protection; chemical sunscreens absorb UV and convert it to heat", "Physical sunscreens are always superior to chemical sunscreens in all situations", "Physical sunscreens must be applied 30 minutes before UV exposure to activate their protection", "Physical sunscreens only protect against UVA while chemical sunscreens only protect against UVB"], options_es: ["Los protectores solares físicos reflejan y dispersan la radiación UV en la superficie de la piel — funcionan inmediatamente después de la aplicación, es menos probable que causen irritación (buenos para la piel sensible), generalmente son fotoestables y proporcionan protección de amplio espectro; los protectores solares químicos absorben la UV y la convierten en calor", "Los protectores solares físicos siempre son superiores a los protectores solares químicos en todas las situaciones", "Los protectores solares físicos deben aplicarse 30 minutos antes de la exposición UV para activar su protección", "Los protectores solares físicos solo protegen contra la UVA mientras que los protectores solares químicos solo protegen contra la UVB"], correct: 0, explanation: "Physical (inorganic) filters: zinc oxide (broad-spectrum, covers UVA and UVB), titanium dioxide (primarily UVB and short UVA). Advantages: photostable, immediate protection upon application, lower irritation potential. Disadvantages: can leave a white cast, thicker texture, may be cosmetically less elegant. Chemical (organic) filters: avobenzone (UVA), octinoxate (UVB), oxybenzone, octisalate — absorb UV through chemical reactions. Need to wait 20–30 min before sun exposure to bind to skin." },
  { id: 333, question: "Rosacea is a chronic skin condition relevant to esthetics because:", question_es: "La rosácea es una condición cutánea crónica relevante para la estética porque:", options: ["Rosacea clients have chronically reactive, easily flushed skin — heat (steam, hot towels), harsh exfoliants, alcohol-based products, and aggressive massage can trigger flare-ups; esthetics services for rosacea require modifications using gentle, non-irritating, cool techniques", "Rosacea is a temporary condition that clears on its own — it has no long-term bearing on esthetics service protocols", "Rosacea is a bacterial skin infection that can be cured with aggressive extraction during facials", "Rosacea clients can receive the same treatments as all other clients — the condition is purely cosmetic and does not affect service selection"], options_es: ["Los clientes con rosácea tienen piel crónicamente reactiva y que se ruboriza fácilmente — el calor (vapor, toallas calientes), los exfoliantes agresivos, los productos a base de alcohol y el masaje agresivo pueden desencadenar brotes; los servicios de estética para la rosácea requieren modificaciones usando técnicas suaves, no irritantes y frescas", "La rosácea es una condición temporal que se cura sola — no tiene ningún efecto a largo plazo en los protocolos de servicio de estética", "La rosácea es una infección cutánea bacteriana que se puede curar con extracciones agresivas durante los faciales", "Los clientes con rosácea pueden recibir los mismos tratamientos que todos los demás clientes — la condición es puramente cosmética y no afecta la selección del servicio"], correct: 0, explanation: "Rosacea (chronic inflammatory vascular condition) presents as facial erythema, flushing, telangiectasias, and in some subtypes, papulopustular lesions mimicking acne. The skin is in a state of chronic vascular reactivity and low-grade inflammation. Triggers: heat (steam, hot towels, saunas), cold, spicy food, alcohol, stress, strong UV. Esthetics approach: gentle cleansers, cool water, anti-inflammatory products, sun protection, no AHA/BHA without caution." },
  { id: 334, question: "Post-inflammatory hyperpigmentation (PIH) is a complication relevant to esthetics because:", question_es: "La hiperpigmentación post-inflamatoria (HPI) es una complicación relevante para la estética porque:", options: ["Aggressive exfoliation, extractions causing trauma, or treatments causing inflammation in darker skin types (Fitzpatrick III–VI) can trigger PIH — the melanocytes respond to inflammation by producing excess melanin, causing dark spots that persist for months to years after the initial trauma", "PIH only occurs after surgery — esthetics services cannot cause PIH under any circumstances", "PIH only affects people with very dark skin (Fitzpatrick VI) — lighter skin types are immune to post-inflammatory darkening", "PIH is always temporary and resolves within one week without any treatment modification"], options_es: ["La exfoliación agresiva, las extracciones que causan traumatismo o los tratamientos que causan inflamación en tipos de piel más oscuros (Fitzpatrick III–VI) pueden desencadenar la HPI — los melanocitos responden a la inflamación produciendo exceso de melanina, causando manchas oscuras que persisten durante meses o años después del traumatismo inicial", "La HPI solo ocurre después de la cirugía — los servicios de estética no pueden causar HPI bajo ninguna circunstancia", "La HPI solo afecta a personas con piel muy oscura (Fitzpatrick VI) — los tipos de piel más claros son inmunes al oscurecimiento post-inflamatorio", "La HPI es siempre temporal y se resuelve dentro de una semana sin ninguna modificación del tratamiento"], correct: 0, explanation: "PIH results when skin injury/inflammation triggers excess melanin production. Risk increases with darker Fitzpatrick types (though it can occur in all types). Common esthetics causes: over-aggressive chemical peels, extracting incorrectly (tearing/forcing), laser or light treatments on wrong skin types, aggressive waxing. Prevention: avoid inflammatory trauma, start with conservative peel percentages, conduct thorough Fitzpatrick assessment, use PIH prevention protocols (Hydroquinone, kojic acid, vitamin C before treatments)." },
  { id: 335, question: "Melasma is a pigmentation condition that occurs most frequently:", question_es: "El melasma es una condición de pigmentación que ocurre con mayor frecuencia:", options: ["In women with hormonal influences (pregnancy — 'mask of pregnancy', oral contraceptives, hormone therapy) plus UV exposure — both hormonal stimulation and UV are required triggers; it appears as symmetrical brown-gray patches on the face, primarily the cheeks, forehead, and upper lip", "Only in men over 50 years of age due to androgen hormone changes", "In children under age 10 from excessive sun exposure without sunscreen", "Exclusively in people with albinism — normal melanin production cannot cause melasma"], options_es: ["En mujeres con influencias hormonales (embarazo — 'máscara del embarazo', anticonceptivos orales, terapia hormonal) más exposición UV — tanto la estimulación hormonal como la UV son desencadenantes requeridos; aparece como parches marrones-grisáceos simétricos en el rostro, principalmente las mejillas, la frente y el labio superior", "Solo en hombres mayores de 50 años debido a los cambios de la hormona andrógeno", "En niños menores de 10 años por exposición excesiva al sol sin protector solar", "Exclusivamente en personas con albinismo — la producción normal de melanina no puede causar melasma"], correct: 0, explanation: "Melasma requires two co-triggers: (1) hormonal stimulation (estrogen/progesterone — most common in pregnancy, OCP users, HRT) and (2) UV exposure (activates melanogenesis in sensitized melanocytes). It is most common in women, darker Fitzpatrick types (IV–VI), in sun-intensive climates. Treatment approach: rigorous daily broad-spectrum SPF, tyrosinase inhibitors (hydroquinone, kojic acid, azelaic acid, vitamin C), and avoiding hormonal triggers." },
  { id: 336, question: "Acne vulgaris develops through which pathophysiological process?", question_es: "El acné vulgar se desarrolla a través de cuál proceso fisiopatológico?", options: ["Four key factors: excess sebum production (sebaceous gland hyperactivity), follicular hyperkeratosis (abnormal shedding of follicle lining cells creating a plug), colonization by Cutibacterium acnes (anaerobic bacteria that feed on sebum), and inflammation (immune response to bacterial byproducts)", "Only bacterial infection — acne is exclusively caused by bacteria that colonize normal skin", "Only hormonal changes — sebum production is the sole factor in all acne development", "Allergic reactions to environmental pollutants — all acne is an allergic response to particles in the air"], options_es: ["Cuatro factores clave: producción excesiva de sebo (hiperactividad de las glándulas sebáceas), hiperqueratosis folicular (desprendimiento anormal de las células del revestimiento folicular que crean un tapón), colonización por Cutibacterium acnes (bacterias anaerobias que se alimentan del sebo) e inflamación (respuesta inmune a los subproductos bacterianos)", "Solo infección bacteriana — el acné es causado exclusivamente por bacterias que colonizan la piel normal", "Solo cambios hormonales — la producción de sebo es el único factor en todo el desarrollo del acné", "Reacciones alérgicas a contaminantes ambientales — todo el acné es una respuesta alérgica a partículas en el aire"], correct: 0, explanation: "Acne pathophysiology — four pillars: (1) Sebum hypersecretion (androgens stimulate sebaceous gland activity), (2) Follicular hyperkeratosis (abnormal desquamation — cells in the follicle lining don't shed normally, forming a comedone plug with sebum), (3) C. acnes proliferation (the bacteria metabolize sebum, producing inflammatory fatty acids and virulence factors), (4) Inflammation (immune response to C. acnes antigens and inflammatory mediators cause papules, pustules, nodules)." },
  { id: 337, question: "An open comedone (blackhead) appears dark in color because:", question_es: "Un comedón abierto (espinilla) aparece oscuro en color porque:", options: ["The pore is open to the air — the sebum and keratin plug at the follicle opening oxidizes and turns dark brown/black through melanin oxidation and lipid peroxidation when exposed to oxygen; not from dirt as is commonly believed", "The pore is filled with dirt particles from the environment that have accumulated over time", "The follicle contains trapped blood that has oxidized at the surface", "Dark pigment from cosmetic products has accumulated in the follicle over time"], options_es: ["El poro está abierto al aire — el sebo y el tapón de queratina en la abertura folicular se oxidan y se vuelven marrón oscuro/negro a través de la oxidación de melanina y la peroxidación lipídica cuando se exponen al oxígeno; no por la suciedad como comúnmente se cree", "El poro está lleno de partículas de suciedad del ambiente que se han acumulado con el tiempo", "El folículo contiene sangre atrapada que se ha oxidado en la superficie", "El pigmento oscuro de los productos cosméticos se ha acumulado en el folículo con el tiempo"], correct: 0, explanation: "Blackhead color: the follicular plug (mixture of cornified cells, sebum, and melanin from shed keratinocytes) is exposed to air at the open follicle pore. The exposure causes: (1) lipid oxidation (fatty acids in sebum oxidize) and (2) melanin oxidation — both turning the material dark. Blackheads are NOT caused by dirt — they form in clean skin. The closed comedone (whitehead) doesn't oxidize because the follicle pore is covered by skin." },
  { id: 338, question: "The Glogau Classification System for photoaging classifies sun damage into four groups. Glogau Type I is characterized by:", question_es: "El Sistema de Clasificación de Glogau para el fotoenvejecimiento clasifica el daño solar en cuatro grupos. El Tipo I de Glogau se caracteriza por:", options: ["Mild photoaging — typically seen in clients in their 20s–30s with minimal wrinkling (lines only with movement/expression), mild pigment changes, no keratoses, minimal visible pore size changes — appropriate for preventive and maintenance skin care", "Severe photoaging with deep furrows, skin laxity, and actinic keratoses requiring medical treatment", "Moderate photoaging with distinct wrinkles visible at rest and early actinic changes", "Advanced photoaging with wrinkles throughout even at rest, skin color changes, and cutaneous malignancy risk"], options_es: ["Fotoenvejecimiento leve — típicamente visto en clientes en sus 20–30 años con arrugas mínimas (líneas solo con movimiento/expresión), cambios de pigmento leves, sin queratosis, cambios mínimos en el tamaño de los poros visibles — apropiado para el cuidado de la piel preventivo y de mantenimiento", "Fotoenvejecimiento grave con surcos profundos, laxitud cutánea y queratosis actínicas que requieren tratamiento médico", "Fotoenvejecimiento moderado con arrugas distintas visibles en reposo y cambios actínicos tempranos", "Fotoenvejecimiento avanzado con arrugas en todas partes incluso en reposo, cambios de color de la piel y riesgo de malignidad cutánea"], correct: 0, explanation: "Glogau Classification: Type I (Mild) — 20s–30s, early photodamage, lines with expression only, no keratoses. Type II (Moderate) — 30s–40s, early wrinkles at rest, some keratoses, some PIH. Type III (Advanced) — 50s+, persistent wrinkles, skin discoloration, keratoses. Type IV (Severe) — 60s–70s, wrinkles throughout, actinic keratoses, malignancy risk. Guides esthetics treatment intensity and peel selection." },
  { id: 339, question: "Vitamin C (ascorbic acid) is used in professional skin care for which primary purpose?", question_es: "La vitamina C (ácido ascórbico) se usa en el cuidado profesional de la piel para cuál propósito principal?", options: ["As an antioxidant that neutralizes free radicals generated by UV exposure, pollution, and metabolic processes — it also inhibits melanin synthesis (tyrosinase inhibition), stimulates collagen synthesis by fibroblasts, and has anti-inflammatory properties", "As an exfoliant — vitamin C dissolves the bonds between corneocytes in the stratum corneum", "As a humectant — vitamin C attracts water to the skin surface for immediate hydration", "Only as a fragrance ingredient — vitamin C's primary role is sensory enhancement of products"], options_es: ["Como antioxidante que neutraliza los radicales libres generados por la exposición UV, la contaminación y los procesos metabólicos — también inhibe la síntesis de melanina (inhibición de la tirosinasa), estimula la síntesis de colágeno por los fibroblastos y tiene propiedades antiinflamatorias", "Como exfoliante — la vitamina C disuelve los lazos entre los corneocitos en el estrato córneo", "Como humectante — la vitamina C atrae agua a la superficie de la piel para una hidratación inmediata", "Solo como ingrediente de fragancia — el papel primario de la vitamina C es la mejora sensorial de los productos"], correct: 0, explanation: "Vitamin C (ascorbic acid) is a multifunctional skin care ingredient: (1) Antioxidant — scavenges free radicals that damage collagen and DNA; (2) Collagen synthesis cofactor — essential for hydroxylation of proline and lysine in collagen (deficiency = impaired collagen), stimulates fibroblast collagen production; (3) Melanogenesis inhibitor — inhibits tyrosinase (enzyme that makes melanin); (4) Anti-inflammatory. Instability (oxidizes quickly) is a formulation challenge — look for stable derivatives (ascorbyl glucoside, vitamin C phosphate)." },
  { id: 340, question: "Retinol and prescription retinoids (tretinoin) are significant in esthetics because:", question_es: "El retinol y los retinoides con receta (tretinoína) son significativos en la estética porque:", options: ["They are the most scientifically proven topical ingredients for photoaging treatment — they increase cell turnover, stimulate collagen synthesis, reduce melanin production, and normalize follicular keratinization (reducing comedone formation); they also cause photosensitivity, requiring sun protection advice", "Retinol is only effective as a dietary supplement — topically applied retinol has no effect on skin appearance", "Retinoids are contraindicated for all clients over 40 years of age", "Retinol and tretinoin are identical products available without a prescription in identical concentrations"], options_es: ["Son los ingredientes tópicos más científicamente comprobados para el tratamiento del fotoenvejecimiento — aumentan la rotación celular, estimulan la síntesis de colágeno, reducen la producción de melanina y normalizan la queratinización folicular (reduciendo la formación de comedones); también causan fotosensibilidad, lo que requiere consejos de protección solar", "El retinol solo es efectivo como suplemento dietético — el retinol aplicado tópicamente no tiene ningún efecto en la apariencia de la piel", "Los retinoides están contraindicados para todos los clientes mayores de 40 años", "El retinol y la tretinoína son productos idénticos disponibles sin receta en concentraciones idénticas"], correct: 0, explanation: "Retinoid hierarchy (activity and prescription requirement): Retinyl palmitate < Retinol < Retinaldehyde (OTC, all convert to retinoic acid in skin) < Tretinoin (prescription). All increase epidermal turnover and stimulate fibroblast activity. Side effects: retinization (initial peeling, redness, dryness) and photosensitivity (must use broad-spectrum SPF). Contraindicated in pregnancy. Estheticians should advise clients using retinoids of their skin's increased sensitivity to treatments." },
  { id: 341, question: "Niacinamide (vitamin B3) in skin care is valued for which combination of benefits?", question_es: "La niacinamida (vitamina B3) en el cuidado de la piel es valorada por cuál combinación de beneficios?", options: ["Reducing hyperpigmentation (inhibits melanosome transfer to keratinocytes), strengthening the skin barrier (stimulates ceramide and fatty acid production), reducing skin redness and inflammation, minimizing pore appearance, and regulating sebum production — with excellent tolerability even in sensitive skin", "Niacinamide is primarily an exfoliant — it removes dead skin cells from the stratum corneum through chemical dissolution", "Niacinamide only works in combination with vitamin C — it has no independent skin benefits", "Niacinamide is primarily an SPF booster — it increases the effectiveness of sunscreen when used together"], options_es: ["Reducir la hiperpigmentación (inhibe la transferencia de melanosomas a los queratinocitos), fortalecer la barrera cutánea (estimula la producción de ceramidas y ácidos grasos), reducir el enrojecimiento e inflamación de la piel, minimizar la apariencia de los poros y regular la producción de sebo — con excelente tolerabilidad incluso en piel sensible", "La niacinamida es principalmente un exfoliante — elimina las células muertas de la piel del estrato córneo a través de la disolución química", "La niacinamida solo funciona en combinación con la vitamina C — no tiene beneficios independientes para la piel", "La niacinamida es principalmente un potenciador del SPF — aumenta la efectividad del protector solar cuando se usa junto"], correct: 0, explanation: "Niacinamide (nicotinamide) benefits: (1) Hyperpigmentation reduction — inhibits melanosome transfer from melanocyte to keratinocyte (reduces visible pigmentation without inhibiting melanin synthesis); (2) Barrier function — enhances ceramide, fatty acid, and involucrin synthesis; (3) Anti-inflammatory — reduces cytokines, redness; (4) Sebum regulation; (5) Minimizes pore appearance. Uniquely gentle — well-tolerated by sensitive, rosacea, and acne-prone skin types." },
  { id: 342, question: "Skin type 'combination' is characterized by:", question_es: "El tipo de piel 'combinación' se caracteriza por:", options: ["An oily T-zone (forehead, nose, chin — areas with highest sebaceous gland density) combined with normal to dry cheeks — product selection must address both areas without over-stripping the dry zones or leaving the oily zones congested", "Skin that changes between completely oily and completely dry with each season", "Skin that is uniformly dry across the entire face", "Skin that alternates between acne and clear skin each month"], options_es: ["Una zona T grasa (frente, nariz, barbilla — áreas con mayor densidad de glándulas sebáceas) combinada con mejillas de normales a secas — la selección de productos debe abordar ambas áreas sin eliminar en exceso las zonas secas ni dejar congestionadas las zonas grasas", "Piel que cambia entre completamente grasa y completamente seca con cada estación", "Piel que es uniformemente seca en todo el rostro", "Piel que alterna entre acné y piel clara cada mes"], correct: 0, explanation: "Combination skin is the most common skin type. The T-zone (forehead, nose, chin) contains the highest density of sebaceous glands and produces more sebum — appearing shinier, with larger visible pores, and more comedone/breakout tendency. Cheeks have lower sebaceous gland density and may appear normal to dry/tight. Service challenge: multi-zone approach — often using different products/techniques in different facial areas." },
  { id: 343, question: "When a client has sensitive skin, esthetics services should be modified to:", question_es: "Cuando un cliente tiene piel sensible, los servicios de estética deben modificarse para:", options: ["Avoid potential triggers — strong fragrance, high concentrations of acids, excessive heat, rough mechanical exfoliation, aggressive massage, and known allergens; use gentle, minimal-ingredient formulations, test products on a small area first, and select calming/barrier-supporting ingredients", "Apply stronger treatment products to desensitize the skin over time — repeated exposure reduces sensitivity", "Avoid all product use on sensitive skin — water-only facials are the only appropriate service", "Limit services to only 5 minutes duration — longer services always trigger reactions in sensitive skin"], options_es: ["Evitar los posibles desencadenantes — fragancia fuerte, altas concentraciones de ácidos, calor excesivo, exfoliación mecánica áspera, masaje agresivo y alérgenos conocidos; usar formulaciones suaves con mínimos ingredientes, probar los productos en una pequeña área primero y seleccionar ingredientes calmantes/de apoyo a la barrera", "Aplicar productos de tratamiento más fuertes para desensibilizar la piel con el tiempo — la exposición repetida reduce la sensibilidad", "Evitar el uso de todos los productos en piel sensible — los faciales solo con agua son el único servicio apropiado", "Limitar los servicios a solo 5 minutos de duración — los servicios más largos siempre desencadenan reacciones en la piel sensible"], correct: 0, explanation: "Sensitive skin has a low threshold for reactivity — it is easily triggered into redness, stinging, burning, or itching by stimuli that normal skin tolerates. The barrier is often compromised (high TEWL). Protocol: (1) always perform patch testing before new products, (2) avoid known irritants (fragrances, SLS, alcohol, high-concentration acids), (3) use calming ingredients (centella asiatica, aloe, bisabolol, allantoin), (4) avoid extreme temperatures, (5) gentle mechanical manipulation only." },
  { id: 344, question: "Intrinsic skin aging (chronological aging) differs from extrinsic aging (photoaging) in that:", question_es: "El envejecimiento intrínseco de la piel (envejecimiento cronológico) difiere del envejecimiento extrínseco (fotoenvejecimiento) en que:", options: ["Intrinsic aging is the genetically programmed reduction in collagen production, cell turnover, and skin function over time — it produces fine lines, thinning, and dryness; extrinsic aging (primarily from UV exposure) adds cumulative damage including deep wrinkles, hyperpigmentation, and loss of elasticity", "Intrinsic aging only affects the epidermis while extrinsic aging only affects the dermis", "They are identical processes — all skin aging is caused by UV exposure", "Extrinsic aging occurs from birth while intrinsic aging only begins after age 50"], options_es: ["El envejecimiento intrínseco es la reducción genéticamente programada en la producción de colágeno, la rotación celular y la función de la piel con el tiempo — produce líneas finas, adelgazamiento y sequedad; el envejecimiento extrínseco (principalmente por la exposición UV) añade daño acumulativo incluyendo arrugas profundas, hiperpigmentación y pérdida de elasticidad", "El envejecimiento intrínseco solo afecta la epidermis mientras que el envejecimiento extrínseco solo afecta la dermis", "Son procesos idénticos — todo el envejecimiento de la piel es causado por la exposición UV", "El envejecimiento extrínseco ocurre desde el nacimiento mientras que el envejecimiento intrínseco solo comienza después de los 50 años"], correct: 0, explanation: "Intrinsic aging: genetic, clock-driven, affects all people equally by rate. Signs: fine lines (from decreased collagen production ~1%/year), gradual thinning, decreased cell turnover (slower healing), reduced sebum (drier skin). Cannot be prevented — only slowed. Extrinsic aging (photoaging): UV exposure, pollution, smoking. Signs: deep wrinkles, coarse texture, mottled pigmentation, leathery appearance, telangiectasias, loss of elasticity. Preventable with sun protection." },
  { id: 345, question: "Free radicals in the context of skin aging are:", question_es: "Los radicales libres en el contexto del envejecimiento de la piel son:", options: ["Unstable molecules with an unpaired electron that react with and damage cellular components (DNA, proteins, lipids) in the skin — generated by UV exposure, pollution, smoking, and metabolic processes; antioxidants in skin care neutralize free radicals to prevent their damaging effects", "Beneficial molecules that stimulate collagen production in the dermis", "The active ingredient class in AHA chemical peel products", "Bacterial toxins produced by C. acnes in acne lesions"], options_es: ["Moléculas inestables con un electrón no pareado que reaccionan y dañan los componentes celulares (ADN, proteínas, lípidos) en la piel — generados por la exposición UV, la contaminación, el tabaquismo y los procesos metabólicos; los antioxidantes en el cuidado de la piel neutralizan los radicales libres para prevenir sus efectos dañinos", "Moléculas beneficiosas que estimulan la producción de colágeno en la dermis", "La clase de ingrediente activo en los productos de peeling químico AHA", "Toxinas bacterianas producidas por C. acnes en las lesiones de acné"], correct: 0, explanation: "Free radicals (reactive oxygen species/ROS) are highly unstable molecules with an unpaired electron — they 'steal' electrons from nearby molecules, causing chain reactions of oxidative damage. UV radiation generates ROS in skin cells, damaging: DNA (mutations, skin cancer risk), lipids (lipid peroxidation — damages membranes), and proteins (collagenase activation — collagen breakdown). Antioxidants (vitamin C, vitamin E, niacinamide, resveratrol, coenzyme Q10) donate electrons to neutralize ROS." },
  { id: 346, question: "Ceramides in skin care products serve which primary function?", question_es: "Las ceramidas en los productos de cuidado de la piel sirven cuál función primaria?", options: ["Replenishing and reinforcing the skin's lipid barrier — ceramides are the predominant lipid in the stratum corneum's intercellular matrix ('mortar' between corneocyte 'bricks'); supplementing ceramides restores barrier integrity, reduces TEWL, and improves dry/sensitive skin's ability to retain moisture", "Providing antioxidant protection by neutralizing free radicals on the skin surface", "Stimulating melanocyte activity to increase natural skin pigmentation", "Acting as chemical exfoliants that loosen corneocyte bonds in the stratum corneum"], options_es: ["Reponiendo y reforzando la barrera lipídica de la piel — las ceramidas son el lípido predominante en la matriz intercelular del estrato córneo ('mortero' entre los 'ladrillos' de corneocitos); suplementar las ceramidas restaura la integridad de la barrera, reduce la TEWL y mejora la capacidad de la piel seca/sensible para retener la humedad", "Proporcionando protección antioxidante al neutralizar los radicales libres en la superficie de la piel", "Estimulando la actividad de los melanocitos para aumentar la pigmentación natural de la piel", "Actuando como exfoliantes químicos que aflojan los lazos de los corneocitos en el estrato córneo"], correct: 0, explanation: "The stratum corneum lipid matrix is composed of ceramides (~50%), cholesterol (~25%), and fatty acids (~15%) — the 'mortar' in the 'brick and mortar' model. Ceramides form lamellar structures that prevent water loss and block pathogen entry. Compromised ceramide levels (from aging, harsh cleansers, over-exfoliation, atopic dermatitis) increase TEWL and sensitivity. Topical ceramide products (especially ceramide 1, 3, 6-II) restore the barrier." },
  { id: 347, question: "Hyaluronic acid (HA) in skin care is valued because:", question_es: "El ácido hialurónico (AH) en el cuidado de la piel es valorado porque:", options: ["It is a naturally occurring humectant glycosaminoglycan that can hold up to 1000 times its weight in water — it draws water to the skin surface (from the environment or deeper tissues) providing immediate visible hydration and plumping of fine lines", "It permanently eliminates all wrinkles by physically filling them from the inside when applied topically", "It is a chemical exfoliant that dissolves dead skin cells similar to glycolic acid", "It stimulates collagen production when injected but has no benefit when applied topically"], options_es: ["Es un glicosaminoglicano humectante de origen natural que puede retener hasta 1000 veces su peso en agua — atrae agua a la superficie de la piel (del ambiente o de los tejidos más profundos) proporcionando hidratación visible inmediata y relleno de las líneas finas", "Elimina permanentemente todas las arrugas al llenarlas físicamente desde adentro cuando se aplica tópicamente", "Es un exfoliante químico que disuelve las células muertas de la piel similar al ácido glicólico", "Estimula la producción de colágeno cuando se inyecta pero no tiene ningún beneficio cuando se aplica tópicamente"], correct: 0, explanation: "Hyaluronic acid (HA) is a naturally occurring polysaccharide found in skin, joints, and connective tissue. It is a powerful humectant — one gram of HA can hold approximately 6 liters of water. In skin care: topical HA provides surface hydration (draws water from environment/transdermal reservoir), plumps fine dehydration lines temporarily, improves texture. Molecular size matters: smaller HA molecules penetrate deeper; larger ones stay at the surface and are more effective at preventing TEWL." },
  { id: 348, question: "Telangiectasias (dilated capillaries, 'spider veins') visible on facial skin are:", question_es: "Las telangiectasias (capilares dilatados, 'arañas vasculares') visibles en la piel facial son:", options: ["Permanently dilated superficial blood vessels visible through the skin — common on the nose and cheeks in rosacea and with prolonged UV exposure, repeated heat exposure, and aging; they can be minimized with careful treatment selection (avoiding heat triggers) and addressed with laser/IPL (medical/medical spa services)", "Temporary redness that resolves immediately after the client is no longer in the treatment room", "Bacterial infections of the capillary walls requiring antibiotic treatment", "Exclusively caused by alcohol consumption — any client with telangiectasias is a regular alcohol user"], options_es: ["Vasos sanguíneos superficiales permanentemente dilatados visibles a través de la piel — comunes en la nariz y las mejillas en la rosácea y con exposición UV prolongada, exposición repetida al calor y envejecimiento; pueden minimizarse con una selección cuidadosa del tratamiento (evitando los desencadenantes de calor) y abordarse con láser/IPL (servicios médicos/spa médico)", "Enrojecimiento temporal que se resuelve inmediatamente después de que el cliente ya no está en la sala de tratamiento", "Infecciones bacterianas de las paredes capilares que requieren tratamiento con antibióticos", "Causadas exclusivamente por el consumo de alcohol — cualquier cliente con telangiectasias es un consumidor habitual de alcohol"], correct: 0, explanation: "Telangiectasias are permanently dilated small blood vessels (capillaries, venules, arterioles) visible at the skin surface. Causes: rosacea (most common facial cause), UV damage (vessel wall damage), repeated heat exposure, trauma, chronic corticosteroid use, genetics. They do not blanch permanently with pressure. Esthetics approach: avoid heat triggers; laser/IPL are the standard treatment (medical/cosmetic procedures, outside basic esthetics scope)." },
  { id: 349, question: "The role of the sebaceous (oil) gland in comedone formation is:", question_es: "El papel de la glándula sebácea (aceite) en la formación de comedones es:", options: ["Excess sebum combines with abnormally shed keratinocytes within the follicle to form the comedone plug — the sebum provides the lipid matrix and the shed cells form the solid component; together they create the blockage that either remains closed (whitehead) or opens and oxidizes (blackhead)", "Sebaceous glands produce sweat that dilutes the follicle contents and prevents comedone formation", "Sebaceous glands attack and destroy the follicle lining, creating the closed comedone", "Sebum has no role in comedone formation — comedones result entirely from excess skin cell production at the follicle opening"], options_es: ["El exceso de sebo se combina con los queratinocitos anormalmente descamados dentro del folículo para formar el tapón del comedón — el sebo proporciona la matriz lipídica y las células descamadas forman el componente sólido; juntos crean el bloqueo que permanece cerrado (puntito blanco) o se abre y se oxida (espinilla)", "Las glándulas sebáceas producen sudor que diluye el contenido del folículo y previene la formación de comedones", "Las glándulas sebáceas atacan y destruyen el revestimiento del folículo, creando el comedón cerrado", "El sebo no tiene ningún papel en la formación de comedones — los comedones resultan completamente del exceso de producción de células de la piel en la abertura del folículo"], correct: 0, explanation: "Comedone formation: (1) androgen stimulation increases sebaceous gland activity → excess sebum, (2) follicular hyperkeratosis — abnormal cohesion of follicle lining cells (they don't shed normally and pile up), (3) the excess sebum + accumulated corneocytes create a plug that fills and dilates the follicle. If the pore opening remains closed → closed comedone (whitehead); if the plug extends to the open pore → oxidizes → open comedone (blackhead)." },
  { id: 350, question: "Sun protection recommendations that an esthetician should provide to all clients include:", question_es: "Las recomendaciones de protección solar que un esteticista debe proporcionar a todos los clientes incluyen:", options: ["Apply broad-spectrum SPF 30+ every morning (even on cloudy days and indoors near windows — UVA penetrates glass), reapply every 2 hours during outdoor activities, wear protective clothing (hats, UPF clothing), seek shade during peak UV hours (10am–4pm), and avoid tanning beds", "SPF is only needed on beach days — daily sunscreen use is excessive for most clients", "SPF 15 provides complete sun protection and does not need to be reapplied once per day", "Sun protection is only relevant for skin cancer prevention — it has no role in anti-aging or hyperpigmentation management in esthetics"], options_es: ["Aplicar SPF de amplio espectro 30+ cada mañana (incluso en días nublados y en interiores cerca de ventanas — la UVA penetra el vidrio), reaplicar cada 2 horas durante actividades al aire libre, usar ropa protectora (sombreros, ropa UPF), buscar sombra durante las horas de mayor UV (10am–4pm) y evitar las camas de bronceado", "El SPF solo se necesita en los días de playa — el uso diario de protector solar es excesivo para la mayoría de los clientes", "El SPF 15 proporciona protección solar completa y no necesita reaplicarse una vez al día", "La protección solar solo es relevante para la prevención del cáncer de piel — no tiene ningún papel en el manejo del antienvejecimiento o la hiperpigmentación en la estética"], correct: 0, explanation: "Sun protection is the single most important anti-aging and hyperpigmentation prevention measure — and a core esthetics education responsibility. Key points: (1) daily broad-spectrum SPF 30+ (not just beach days), (2) UVA penetrates glass and clouds (cloudy/indoors ≠ UV-free), (3) reapply every 2 hours when outdoor, (4) adequate amount (most people apply only 25–50% of the required amount), (5) complementary protective measures (clothing, shade). SPF is foundational to any skin care treatment outcome." },
]

